    private $db;private $entity;private $root;
    public function __construct($db,$entity=null){global$conf;$this->db=$db;$this->entity=$entity===null?(int)$conf->entity:(int)$entity;$this->root=rtrim((string)$conf->chinaplanetoperations->dir_output,'/').'/qc/'.$this->entity;}

    public function publish($operationId,$overallResult,$overrideReason,$publisherId)
    {
