        $this->db->begin();try{$operation=$this->object('SELECT * FROM '.MAIN_DB_PREFIX.'cpo_operation WHERE entity='.$this->entity.' AND rowid='.(int)$operationId." AND service_type='quality_control' AND status=1 FOR UPDATE");if(!$operation)throw new RuntimeException('QC operation not found.');$stateRow=$this->object('SELECT data_json FROM '.MAIN_DB_PREFIX.'cpo_operation_data WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId." AND section_code='qc_plan_state' FOR UPDATE");$state=$stateRow?json_decode((string)$stateRow->data_json,true):null;if(!is_array($state)||$state['state']!=='reviewed'||!empty($state['superseded_by_operation_id']))throw new RuntimeException('QC inspection must finish supervisor review and remain current before publication.');
            $checkpoints=$this->rows('SELECT * FROM '.MAIN_DB_PREFIX.'cpo_qc_checkpoint WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId.' ORDER BY position,rowid');$evidence=$this->rows('SELECT * FROM '.MAIN_DB_PREFIX."cpo_qc_evidence WHERE entity=".$this->entity.' AND fk_operation='.(int)$operationId." AND upload_status='finalized' AND review_status='approved_customer' AND customer_visible=1 ORDER BY fk_checkpoint,rowid");
