            $hasFailure=false;foreach($checkpoints as$cp)if($cp['result_code']==='fail')$hasFailure=true;$aqlRejected=!empty($state['aql']['outcome'])&&$state['aql']['outcome']==='reject';if($overallResult==='pass'&&($hasFailure||$aqlRejected)&&trim((string)$overrideReason)==='')throw new RuntimeException('Publishing Pass over a failed checkpoint or rejected AQL requires an override rationale.');
            $snapshot=$this->verifiedSnapshot($operationId);$safe=isset($snapshot['publication_safe'])&&is_array($snapshot['publication_safe'])?$snapshot['publication_safe']:null;if(!$safe||empty($safe['operation']['ref'])||empty($safe['operation']['title'])||!isset($safe['fields'])||!is_array($safe['fields']))throw new RuntimeException('Frozen publication-safe QC snapshot is missing.');
            $version=(int)$this->scalar('SELECT COALESCE(MAX(version_no),0)+1 value FROM '.MAIN_DB_PREFIX.'cpo_qc_publication WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId.' FOR UPDATE');$publicUuid=$this->uuid();$now=$this->now();$sections=$this->sections($checkpoints,$evidence);$summary=$this->summary($checkpoints);
            $reviewer=$this->object('SELECT login,firstname,lastname FROM '.MAIN_DB_PREFIX.'user WHERE rowid='.(int)$state['reviewed_by'].' AND entity IN (0,'.$this->entity.')');$reviewerName=$reviewer?(trim((string)$reviewer->firstname.' '.(string)$reviewer->lastname)?:trim((string)$reviewer->login)):'China Planet QC';
            $frozenOperation=(object)array('ref'=>(string)$safe['operation']['ref'],'title'=>(string)$safe['operation']['title']);
            $publication=array('schema_version'=>1,'publication_id'=>$publicUuid,'version'=>$version,'overall_result'=>$overallResult,'operation'=>array('ref'=>$frozenOperation->ref,'title'=>$frozenOperation->title),'inspection'=>array('inspected_at'=>isset($state['submitted_at'])?$state['submitted_at']:null,'reviewed_at'=>isset($state['reviewed_at'])?$state['reviewed_at']:null,'published_at'=>$now,'reviewed_by'=>$reviewerName,'version'=>$version,'aql'=>$this->publicAql(isset($state['aql'])?$state['aql']:array())),'summary'=>$summary,'public_note'=>isset($safe['public_note'])?$safe['public_note']:null,'fields'=>$this->legacyFields($safe['fields'],$overallResult),'documents'=>array(),'sections'=>$sections);
            $customerEvidence=$this->publicationEvidence($sections,$evidence);$createdPdf=$this->generatePdf($frozenOperation,$publication,$customerEvidence);$pdfSize=filesize($createdPdf);$pdfHash=hash_file('sha256',$createdPdf);$publication['documents'][]=array('id'=>$publicUuid,'kind'=>'document','name'=>'QC-'.$frozenOperation->ref.'-v'.$version.'.pdf','mime_type'=>'application/pdf','size_bytes'=>(int)$pdfSize,'version'=>$version,'approved_at'=>$now);$publication['inspection']['pdf']=array('id'=>$publicUuid,'name'=>'QC-'.$frozenOperation->ref.'-v'.$version.'.pdf','size_bytes'=>(int)$pdfSize);
