    }

    private function sections(array$checkpoints,array$evidence){$byCheckpoint=array();foreach($evidence as$item){$this->assertSafeFile($item);$byCheckpoint[(int)$item['fk_checkpoint']][]=array('id'=>(string)$item['client_uuid'],'kind'=>(string)$item['evidence_type'],'caption'=>$this->stringOrNull($item['caption']),'mime_type'=>(string)$item['safe_mime'],'size_bytes'=>(int)$item['safe_size'],'sha256'=>(string)$item['safe_sha256']);}$sections=array();foreach($checkpoints as$cp){if($cp['record_kind']==='finding'&&($cp['review_status']!=='approved_customer'||(int)$cp['customer_visible']!==1))continue;$code=(string)$cp['section_code'];if(!isset($sections[$code]))$sections[$code]=array('code'=>$code,'title'=>(string)$cp['section_label'],'checkpoints'=>array());$sections[$code]['checkpoints'][]=array('id'=>(string)$cp['client_uuid'],'requirement'=>(string)$cp['requirement_text'],'expected_value'=>$this->stringOrNull($cp['expected_value']),'tolerance'=>$this->stringOrNull($cp['tolerance_text']),'observation'=>$this->stringOrNull($cp['observation']),'result'=>(string)$cp['result_code'],'severity'=>(string)$cp['severity'],'public_note'=>$this->stringOrNull($cp['public_note']),'evidence'=>isset($byCheckpoint[(int)$cp['rowid']])?$byCheckpoint[(int)$cp['rowid']]:array());}return array_values($sections);}
    private function summary(array$rows){$summary=array('total'=>0,'pass'=>0,'fail'=>0,'not_applicable'=>0,'critical'=>0,'major'=>0,'minor'=>0);foreach($rows as$row){if($row['record_kind']==='finding'&&$row['review_status']!=='approved_customer')continue;$summary['total']++;if(isset($summary[$row['result_code']]))$summary[$row['result_code']]++;if($row['result_code']==='fail'&&isset($summary[$row['severity']]))$summary[$row['severity']]++;}return$summary;}
    private function legacyFields(array$service,$result){$allowed=array('product_name','model_no','product_details','customer_notes','customer_warnings','inspection_standard','aql_level','sample_size','critical_limit','major_limit','minor_limit','corrective_action');$fields=array();foreach($allowed as$code)if(isset($service[$code])&&trim((string)$service[$code])!=='')$fields[]=array('code'=>$code,'value'=>substr((string)$service[$code],0,10000));$fields[]=array('code'=>'inspection_result','value'=>$result);return$fields;}
    private function publicationEvidence(array$sections,array$rows){$allowed=array();foreach($sections as$section)foreach($section['checkpoints']as$checkpoint)foreach($checkpoint['evidence']as$item)$allowed[(string)$item['id']]=true;return array_values(array_filter($rows,function($row)use($allowed){return isset($allowed[(string)$row['client_uuid']]);}));}
    private function reviewPackageHash($operationId){$snapshot=$this->verifiedSnapshot($operationId);$package=array('snapshot_sha256'=>(string)$snapshot['snapshot_sha256'],'checkpoints'=>array(),'evidence'=>array());foreach($this->rows('SELECT client_uuid,record_kind,section_code,section_label,requirement_text,expected_value,tolerance_text,observation,result_code,severity,public_note,review_status,customer_visible,position,revision FROM '.MAIN_DB_PREFIX.'cpo_qc_checkpoint WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId.' ORDER BY rowid')as$row)$package['checkpoints'][]=$row;foreach($this->rows('SELECT client_uuid,fk_checkpoint,evidence_type,caption,upload_status,review_status,customer_visible,original_sha256,safe_mime,safe_size,safe_sha256,revision FROM '.MAIN_DB_PREFIX.'cpo_qc_evidence WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId." AND upload_status='finalized' ORDER BY rowid")as$row)$package['evidence'][]=$row;return hash('sha256',$this->canonicalJson($package));}
    private function verifiedSnapshot($operationId){$snapshot=$this->section($operationId,'qc_source_snapshot');$stored=(string)($snapshot['snapshot_sha256']??'');$payload=$snapshot;unset($payload['snapshot_sha256']);$actual=hash('sha256',$this->canonicalJson($payload));if(!preg_match('/^[a-f0-9]{64}$/',$stored)||!hash_equals($stored,$actual))throw new RuntimeException('QC source snapshot integrity check failed.');return$snapshot;}
    private function publicAql(array$aql){if(empty($aql['enabled'])||empty($aql['calculation'])||!is_array($aql['calculation']))return null;$c=$aql['calculation'];return array('standard'=>isset($c['standard'])?(string)$c['standard']:null,'edition'=>isset($c['edition'])?(string)$c['edition']:null,'sampling'=>isset($c['sampling'])?(string)$c['sampling']:null,'inspection'=>isset($c['inspection'])?(string)$c['inspection']:null,'level'=>isset($c['level'])?(string)$c['level']:null,'lot_size'=>isset($c['lot_size'])?(int)$c['lot_size']:null,'classes'=>isset($c['classes'])&&is_array($c['classes'])?$c['classes']:array(),'observed'=>isset($aql['observed'])&&is_array($aql['observed'])?$aql['observed']:null,'outcome'=>isset($aql['outcome'])?(string)$aql['outcome']:null);}
    private function generatePdf($operation,array$publication,array$evidence)
    {
        if(function_exists('dol_include_once'))dol_include_once('/includes/tecnickcom/tcpdf/tcpdf.php');
        if(!class_exists('TCPDF'))throw new RuntimeException('PDF engine is unavailable; QC publication was not created.');
