        $pdf=new TCPDF('P','mm','A4',true,'UTF-8',false);$pdf->SetCreator('ChinaPlanetOS');$pdf->SetAuthor('China Planet');$pdf->SetTitle('QC '.$operation->ref.' v'.$publication['version']);$pdf->setPrintHeader(false);$pdf->setPrintFooter(true);$pdf->SetMargins(14,14,14);$pdf->AddPage();$pdf->SetFont('dejavusans','B',18);$pdf->Write(0,'QC Report · '.$operation->ref);$pdf->Ln(10);$pdf->SetFont('dejavusans','',10);
        $pdf->writeHTML('<table cellpadding="5" border="1"><tr><td><b>Result</b></td><td>'.htmlspecialchars($publication['overall_result'],ENT_QUOTES,'UTF-8').'</td></tr><tr><td><b>Version</b></td><td>'.(int)$publication['version'].'</td></tr><tr><td><b>Published</b></td><td>'.htmlspecialchars($publication['inspection']['published_at'],ENT_QUOTES,'UTF-8').'</td></tr><tr><td><b>Summary</b></td><td>'.(int)$publication['summary']['pass'].' pass · '.(int)$publication['summary']['fail'].' fail · '.(int)$publication['summary']['not_applicable'].' N/A</td></tr></table>',true,false,true,false,'');
        foreach($publication['sections']as$section){$pdf->Ln(5);$pdf->SetFont('dejavusans','B',13);$pdf->Write(0,$section['title']);$pdf->Ln(7);$pdf->SetFont('dejavusans','',9);foreach($section['checkpoints']as$cp){$html='<table cellpadding="4" border="1"><tr><td width="24%"><b>Requirement</b></td><td width="76%">'.htmlspecialchars($cp['requirement'],ENT_QUOTES,'UTF-8').'</td></tr><tr><td><b>Actual</b></td><td>'.htmlspecialchars((string)$cp['observation'],ENT_QUOTES,'UTF-8').'</td></tr><tr><td><b>Result</b></td><td>'.htmlspecialchars($cp['result'].' · '.$cp['severity'],ENT_QUOTES,'UTF-8').'</td></tr></table>';$pdf->writeHTML($html,true,false,true,false,'');}}
        $images=0;foreach($evidence as$item){if($item['evidence_type']!=='image'||$images>=12)continue;$this->assertSafeFile($item);$path=realpath($this->root.'/evidence/'.$item['safe_stored_name']);if($pdf->GetY()>245)$pdf->AddPage();$pdf->Ln(3);$pdf->SetFont('dejavusans','',8);$pdf->Write(0,trim((string)$item['caption'])!==''?(string)$item['caption']:'Approved inspection image');$pdf->Ln(4);$pdf->Image($path,'','',45,34,'JPG','','',true,150,'',false,false,1,false,false,false);$pdf->Ln(36);$images++;}
        $url=function_exists('dol_buildpath')?dol_buildpath('/custom/chinaplanetcustomercenter/qc_report.php?report='.rawurlencode($publication['publication_id']),2):'/custom/chinaplanetcustomercenter/qc_report.php?report='.rawurlencode($publication['publication_id']);if($pdf->GetY()>235)$pdf->AddPage();$pdf->Ln(5);$pdf->SetFont('dejavusans','',9);$pdf->Write(0,'Latest online report (login required)');$pdf->write2DBarcode($url,'QRCODE,M',15,$pdf->GetY()+5,35,35,array('border'=>0),'N');$pdf->Output($target,'F');if(!is_file($target)||filesize($target)<=0||!chmod($target,0600))throw new RuntimeException('Unable to create secure QC PDF.');return$target;
    }
    private function assertSafeFile($row){$root=realpath($this->root.'/evidence');$path=$root?realpath($root.'/'.$row['safe_stored_name']):false;if(!$root||!$path||!is_file($path)||is_link($path)||strpos($path,rtrim($root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)!==0||(int)filesize($path)!==(int)$row['safe_size']||!hash_equals((string)$row['safe_sha256'],(string)hash_file('sha256',$path)))throw new RuntimeException('Approved QC evidence failed publication verification.');}
    private function section($op,$code){$row=$this->object('SELECT data_json FROM '.MAIN_DB_PREFIX.'cpo_operation_data WHERE entity='.$this->entity.' AND fk_operation='.(int)$op.' AND section_code='.$this->q($code));$data=$row?json_decode((string)$row->data_json,true):array();return is_array($data)?$data:array();}
    private function canonicalJson($data){$normal=function($value)use(&$normal){if(!is_array($value))return$value;if(array_keys($value)!==range(0,count($value)-1))ksort($value,SORT_STRING);foreach($value as$key=>$item)$value[$key]=$normal($item);return$value;};return$this->json($normal($data));}
    private function ensureDirectory($path){$cursor=$path;while(!file_exists($cursor)&&dirname($cursor)!==$cursor)$cursor=dirname($cursor);if(is_link($cursor)||($cursor!==''&&!is_dir($cursor)))throw new RuntimeException('Unsafe QC publication path.');if(!is_dir($path)&&!mkdir($path,0700,true))throw new RuntimeException('Unable to create QC publication storage.');if(is_link($path)||!chmod($path,0700))throw new RuntimeException('Unable to secure QC publication storage.');}
    private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
    private function stringOrNull($value){return trim((string)$value)!==''?(string)$value:null;}private function scalar($sql){$row=$this->object($sql);return$row?$row->value:null;}private function object($sql){$res=$this->db->query($sql);return$res?$this->db->fetch_object($res):null;}private function rows($sql){$rows=array();$res=$this->db->query($sql);while($res&&($row=$this->db->fetch_object($res)))$rows[]=get_object_vars($row);return$rows;}private function json($data){$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION);if($json===false)throw new RuntimeException('Unable to encode QC publication.');return$json;}private function nullable($value){return$value===null||$value===''?'NULL':$this->q($value);}private function q($value){return"'".$this->db->escape((string)$value)."'";}private function now(){return$this->db->idate(dol_now());}private function fail(){throw new RuntimeException($this->db->lasterror());}
}
